    joinery: { rate: 0.05, qty: 1, price: 12, inputs: { wood: 2.5 }, perWorker: 2.5 },
    mill: { rate: 0.5, qty: 1, price: 2, inputs: { grain: 0.5 }, perWorker: 15 },
