    if (!s.offices.watch && v.chest > 70 && rand(s) < 0.1) { const c = officerCandidates(s)[0]; if (c) { appointOfficer(s, 'watch', c); govLog(s, 'Elder ' + e.name + ' appoints ' + c.name + ' Village Watchman.', 'info'); } }
