    for (let x = 60; x <= 92; x += 8.5) for (let z = -62; z <= 40; z += 8.5) if (Math.abs(z - 4) > 5) sites.push({ x, z });
    for (let x = -92; x <= -70; x += 8.5) for (let z = -40; z <= 40; z += 8.5) sites.push({ x, z });
